const CSS=".wrap{position:relative;width:100%;height:100%;min-width:0;min-height:0;display:grid;gap:6px;padding:10px;color:var(--ink);\n  grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr) auto;grid-template-areas:\"info\" \"stage\" \"foot\"}\n.info{grid-area:info;min-width:0;display:grid;gap:2px;justify-items:center;text-align:center}\n.lab{font-size:12px;color:var(--muted);letter-spacing:.08em}\n.cnt{display:flex;align-items:baseline;justify-content:center;gap:4px;min-width:0}\n.num{font-size:44px;font-weight:800;line-height:1;font-variant-numeric:tabular-nums;color:var(--ink);overflow-wrap:anywhere}\n.unit{font-size:14px;color:var(--muted)}\n.meta{font-size:11.5px;color:var(--muted)}\n.stage{grid-area:stage;position:relative;display:block;min-width:0;min-height:0;padding:0;border:0;border-radius:18px;\n  background:transparent;color:inherit;cursor:pointer;touch-action:manipulation;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent}\n.stage:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.fish{position:absolute;inset:0;width:100%;height:100%;overflow:visible;transform-origin:50% 92%;pointer-events:none}\n.mallet{transform-box:view-box;transform-origin:178px 14px;transform:rotate(30deg)}\n.fish.hit{animation:squash .17s ease-out}\n.mallet.hit{animation:swing .17s ease-out}\n@keyframes squash{0%{transform:scale(1)}35%{transform:scale(.955,.92)}100%{transform:scale(1)}}\n@keyframes swing{0%{transform:rotate(30deg)}35%{transform:rotate(8deg)}100%{transform:rotate(30deg)}}\n.pops{position:absolute;inset:0;pointer-events:none;overflow:hidden}\n.pop{position:absolute;bottom:56%;font-weight:800;font-size:20px;color:var(--accent);opacity:0;animation:rise .8s ease-out forwards}\n@keyframes rise{0%{opacity:0;transform:translate(-50%,0) scale(.8)}15%{opacity:1}100%{opacity:0;transform:translate(-50%,-46px) scale(1.1)}}\n.foot{grid-area:foot;display:flex;justify-content:center;min-width:0}\n.snd{border:1px solid var(--line);background:var(--button-paper);color:var(--ink);border-radius:999px;padding:5px 14px;font-size:12px;line-height:1.3}\n.snd[aria-pressed=\"false\"]{color:var(--muted)}\n.snd:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n\n.card[data-size=\"3x3\"] .wrap{padding:6px 8px 8px;gap:0;grid-template-rows:auto minmax(0,1fr);grid-template-areas:\"info\" \"stage\"}\n.card[data-size=\"3x3\"] .info{grid-auto-flow:column;justify-content:center;align-items:baseline;column-gap:8px;padding-right:56px}\n.card[data-size=\"3x3\"] .lab{font-size:11px;letter-spacing:.04em}\n.card[data-size=\"3x3\"] .meta{display:none}\n.card[data-size=\"3x3\"] .num{font-size:30px}\n.card[data-size=\"3x3\"] .unit{font-size:12px}\n.card[data-size=\"3x3\"] .foot{position:absolute;top:6px;right:6px}\n.card[data-size=\"3x3\"] .snd{padding:2px 8px;font-size:11px}\n\n.card[data-size=\"6x3\"] .wrap{gap:4px 12px;padding:10px 14px;grid-template-columns:minmax(0,1fr) minmax(0,1fr);grid-template-rows:minmax(0,1fr) auto;\n  grid-template-areas:\"stage info\" \"stage foot\"}\n.card[data-size=\"6x3\"] .info{justify-items:start;text-align:left;align-content:center}\n.card[data-size=\"6x3\"] .cnt{justify-content:flex-start}\n.card[data-size=\"6x3\"] .num{font-size:52px}\n.card[data-size=\"6x3\"] .foot{justify-content:flex-start}\n\n.card[data-size=\"3x6\"] .num{font-size:50px}\n.card[data-size=\"3x6\"] .wrap{padding:12px 10px 12px}\n\n.card[data-size=\"6x6\"] .wrap{padding:16px 18px;gap:8px}\n.card[data-size=\"6x6\"] .lab{font-size:14px}\n.card[data-size=\"6x6\"] .num{font-size:76px}\n.card[data-size=\"6x6\"] .unit{font-size:18px}\n.card[data-size=\"6x6\"] .meta{font-size:13px}\n.card[data-size=\"6x6\"] .snd{font-size:13px;padding:6px 16px}\n\n@media (prefers-reduced-motion:reduce){.fish.hit,.mallet.hit{animation:none}.pop{display:none}}\n";
function knockSound(ui){
  try{
    const ac=ui.audio||(ui.audio=new AudioContext());
    if(ac.state==='suspended')ac.resume();
    const t=ac.currentTime,out=ac.createGain();
    out.gain.value=0.9;out.connect(ac.destination);
    const tone=(type,f0,f1,dur,peak)=>{
      const o=ac.createOscillator(),g=ac.createGain();
      o.type=type;o.frequency.setValueAtTime(f0,t);o.frequency.exponentialRampToValueAtTime(f1,t+dur*0.6);
      g.gain.setValueAtTime(0.0001,t);g.gain.exponentialRampToValueAtTime(peak,t+0.004);g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
      o.connect(g);g.connect(out);o.start(t);o.stop(t+dur+0.02);
    };
    tone('sine',540,180,0.17,0.55);
    tone('triangle',1050,320,0.07,0.25);
  }catch(e){}
}

function dateLabel(){
  const d=new Date();
  return (d.getMonth()+1)+'月'+d.getDate()+'日 周'+'日一二三四五六'[d.getDay()];
}

function fishArt(el,hitDelay){
  const hit=hitDelay!==null;
  const delay=hit?{animationDelay:hitDelay+'ms'}:{};
  return el('svg',{viewBox:'0 0 200 170',class:'fish'+(hit?' hit':''),'aria-hidden':'true',style:delay},
    el('ellipse',{cx:100,cy:160,rx:62,ry:7,fill:'var(--ink)',opacity:'.12'}),
    el('ellipse',{cx:100,cy:100,rx:74,ry:58,fill:'var(--accent)'}),
    el('path',{d:'M62 88 Q100 64 138 88',fill:'none',stroke:'var(--on-accent)','stroke-width':4,'stroke-linecap':'round',opacity:'.35'}),
    el('path',{d:'M72 100 Q100 82 128 100',fill:'none',stroke:'var(--on-accent)','stroke-width':4,'stroke-linecap':'round',opacity:'.3'}),
    el('ellipse',{cx:76,cy:68,rx:26,ry:11,fill:'var(--on-accent)',opacity:'.22',transform:'rotate(-24 76 68)'}),
    el('path',{d:'M44 116 Q100 150 156 116',fill:'none',stroke:'var(--on-accent)','stroke-width':8,'stroke-linecap':'round'}),
    el('g',{class:'mallet'+(hit?' hit':''),style:delay},
      el('line',{x1:178,y1:14,x2:128,y2:58,stroke:'var(--ink)','stroke-width':5,'stroke-linecap':'round'}),
      el('circle',{cx:124,cy:61,r:11,fill:'var(--accent-alt)'})));
}

function mount(ctx){
  const {root,el,state,ui,update,day}=ctx;
  const today=day();
  const base=state.date===today?(Number(state.count)||0):0;
  const shown=()=>Math.max(base,ui.expect||0);
  const soundOn=state.sound!==false;
  const now=Date.now();
  const sinceHit=ui.hitAt?now-ui.hitAt:null;
  ui.pops=(ui.pops||[]).filter(p=>now-p.t<800);

  const num=el('div',{class:'num'},String(shown()));
  const popEl=p=>el('span',{class:'pop',style:{left:p.x+'%',animationDelay:(-(Date.now()-p.t))+'ms'}},'+1');
  const pops=el('div',{class:'pops'},ui.pops.map(popEl));
  const fish=fishArt(el,sinceHit!==null&&sinceHit<200?-sinceHit:null);

  function replay(){
    const mallet=fish.querySelector('.mallet');
    for(const n of [fish,mallet]){
      n.classList.remove('hit');n.style.animationDelay='0ms';
      void n.getBoundingClientRect();
      n.classList.add('hit');
    }
  }

  function tap(){
    ui.expect=shown()+1;
    ui.inflight=(ui.inflight||0)+1;
    ui.hitAt=Date.now();
    const p={t:ui.hitAt,x:36+Math.random()*28};
    ui.pops.push(p);
    num.textContent=String(ui.expect);
    stage.setAttribute('aria-label','敲木鱼，今天已敲 '+ui.expect+' 下');
    pops.append(popEl(p));
    replay();
    if(soundOn)knockSound(ui);
    update(s=>{
      const t=day();
      const c=s.date===t?(Number(s.count)||0):0;
      return {...s,date:t,count:c+1};
    }).catch(()=>{}).finally(()=>{
      ui.inflight=Math.max(0,(ui.inflight||0)-1);
      if(!ui.inflight)ui.expect=null;
    });
  }

  const stage=el('button',{type:'button',class:'stage','aria-label':'敲木鱼，今天已敲 '+shown()+' 下',
    onpointerdown:ev=>{if(ev.button>0)return;ev.preventDefault();ui.focus=null;tap();},
    onkeydown:ev=>{if((ev.key===' '||ev.key==='Enter')&&!ev.repeat){ev.preventDefault();ui.focus='stage';tap();}},
    onblur:ev=>{if(ev.relatedTarget)ui.focus=null;}},
    fish,pops);

  const snd=el('button',{type:'button',class:'snd','aria-pressed':String(soundOn),
    onclick:ev=>{ui.focus=ev.detail===0?'snd':null;update(s=>({...s,sound:s.sound===false})).catch(()=>{});}},
    soundOn?'声音：开':'声音：关');

  root.append(el('div',{class:'wrap'},
    el('div',{class:'info'},
      el('div',{class:'lab'},'今日敲击'),
      el('div',{class:'cnt'},num,el('span',{class:'unit'},'下')),
      el('div',{class:'meta'},dateLabel()+' · 每天零点清零')),
    stage,
    el('div',{class:'foot'},snd)));
  // 每次保存后卡片会重绘，键盘操作时把焦点放回原来的按钮
  if(ui.focus==='stage')stage.focus({preventScroll:true});
  else if(ui.focus==='snd')snd.focus({preventScroll:true});
}

